                     </Button>
                   )}
                 </div>
               </form>
               {rejecting && <Separator />}
               {rejecting && (
                 <form noValidate onSubmit={reject}>
                   <FieldSet disabled={pending}>
                     <FieldGroup>
                       <Field data-invalid={Boolean(errors.reason)}>
                         <FieldLabel htmlFor="rejection-reason">Reason for the applicant</FieldLabel>
                         <Textarea
                           aria-invalid={Boolean(errors.reason)}
                           id="rejection-reason"
                           name="reason"
                           required
                         />
                         <FieldError>{errors.reason}</FieldError>
                       </Field>
                       <div className="flex flex-wrap gap-2">
                         <Button type="submit" variant="destructive">
                           {pending && <Spinner data-icon="inline-start" />}Reject and notify
                           applicant
                         </Button>
                         <Button onClick={() => setRejecting(false)} type="button" variant="outline">
                           Cancel
                         </Button>
                       </div>
                     </FieldGroup>
                   </FieldSet>
                 </form>
               )}
             </>
           )}
         </div>
       )}
       {state.status !== "loading" &&
         state.status !== "ready" &&
         state.status !== "missing" &&
         state.status !== "unselected" && (
           <ReviewAccess outcome={state.status} retry={() => void retry()} />
         )}
       {state.status === "ready" && planState.status === "ready" && (
         <AlertDialog onOpenChange={(open) => !pending && setAccepting(open)} open={accepting}>
           <AlertDialogContent>
             <AlertDialogHeader>
               <AlertDialogTitle>Accept this signup request?</AlertDialogTitle>
               <AlertDialogDescription>
